"use client";
import { useState } from "react";
import "./InterestRate.css";
import { FaFilePdf, FaDownload, FaCalendarAlt } from "react-icons/fa";

export default function InterestRate() {
  const currentRates = {
    effectiveDate: "2082/09/30", // Date from your PDF [cite: 5]
    baseRate: "12.52%",           // From PDF [cite: 12]
    savings: [
      { name: "Asal Bachat (असल वचत)", rate: "7.2%" },
      { name: "Special Bachat (विशेष बचत)", rate: "7.5%" },
      { name: "Sunaulo Bhawishya (सुनौलो भविष्य)", rate: "7.99%" }, // [cite: 19]
      { name: "Individual/Group/Daily", rate: "7.2%" }, // [cite: 19]
    ],
    loans: [
      { name: "General/Micro-Enterprise (Fixed)", rate: "14.38%" }, // 
      { name: "Business/Seasonal (Fixed)", rate: "14.38%" }, // 
      { name: "Adjustable Rate", rate: "Base + 1.86%" }, // 
    ],
  };

  const pdfArchive = [
    { year: "2082/83", months: ["Shrawan", "Asoj", "Poush", "Chaitra"] },
    { year: "2081/82", months: ["Full Year Archive"] },
    { year: "2080/81", months: ["Full Year Archive"] },
  ];

  const [selectedYear, setSelectedYear] = useState(pdfArchive[0].year);
  const activeYearData = pdfArchive.find((a) => a.year === selectedYear);

  return (
    <div className="interest-page">
      
      {/* HEADER SECTION */}
      <div className="interest-hero">
        <h1>Rates & Charges</h1>
        <p>Official interest rates for Infinity Laghubitta Bittiya Sanstha Ltd.</p> [cite: 4]
      </div>

      <div className="interest-content">

        {/* SIDEBAR ARCHIVE */}
        <aside className="archive-sidebar">
          <h3><FaCalendarAlt /> Archive</h3>
          <ul>
            {pdfArchive.map((item) => (
              <li
                key={item.year}
                className={selectedYear === item.year ? "active" : ""}
                onClick={() => setSelectedYear(item.year)}
              >
                F.Y. {item.year}
              </li>
            ))}
          </ul>
        </aside>

        {/* MAIN DETAILS */}
        <main className="details-main">

          {/* QUICK SUMMARY CARDS */}
          <div className="current-summary">
            <h2>Interest Rates (Effective: {currentRates.effectiveDate})</h2> [cite: 5]
            <div className="rate-brief-grid">
              <div className="brief-box">
                <span>Avg. Base Rate</span>
                <h4>{currentRates.baseRate}</h4> [cite: 12]
              </div>
              <div className="brief-box">
                <span>Loan (Fixed Rate)</span>
                <h4>14.38%</h4> 
              </div>
            </div>
          </div>

          {/* PRODUCT TABLES */}
          <div className="details-table">
            <h3>Detailed Interest Breakdown</h3>
            <div className="table-grid">
              <div className="table-box">
                <h4>Savings</h4>
                <ul>
                  {currentRates.savings.map((item, i) => (
                    <li key={i}>
                      <span>{item.name}</span>
                      <span className="text-green">{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>
              <div className="table-box">
                <h4>Loans</h4>
                <ul>
                  {currentRates.loans.map((item, i) => (
                    <li key={i}>
                      <span>{item.name}</span>
                      <span className="text-blue">{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>

          {/* DOWNLOADABLE PDF LIST */}
          <div className="pdf-section">
            <h3>Download Official Notices ({selectedYear})</h3>
            <div className="pdf-list">
              {activeYearData?.months.map((month, index) => {
                // Formatting logic for filename consistency
                const yearPath = selectedYear.replace("/", "-"); 
                const monthFile = month.toLowerCase().replace(/\s+/g, "-");
                
                return (
                  <div key={index} className="pdf-card">
                    <div className="pdf-info">
                      <FaFilePdf className="pdf-icon-blue" />
                      <span>{month} Notice</span>
                    </div>
                    <a
                      href={`/assets/pdf/interest/rate-${yearPath}-${monthFile}.pdf`}
                      target="_blank"
                      rel="noreferrer"
                      className="btn-download"
                    >
                      <FaDownload /> Download PDF
                    </a>
                  </div>
                );
              })}
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
